async function adminMatches(){
 const {data:{session}}=await db.auth.getSession(); if(!session)return admin();
 const leagues=(await db.from("leagues").select("id,name").order("name")).data||[];
 shell("Admin · Mechi",'<div class="cards"><div class="card"><h2>Tengeneza Fixture</h2><form id="matchForm" class="form"><select id="mLeague" required><option value="">Ligi</option>'+leagues.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join("")+'</select><select id="mSeason" required><option value="">Msimu</option></select><select id="mStage"><option value="">Stage (optional)</option></select><select id="mHome" required><option value="">Home</option></select><select id="mAway" required><option value="">Away</option></select><input id="mDate" type="datetime-local" required><input id="mVenue" placeholder="Uwanja"><input id="mRound" placeholder="Round / Jina la hatua"><input id="mLeg" type="number" min="1" value="1" placeholder="Leg"><button class="btn">Hifadhi Fixture</button><div id="matchMsg"></div></form></div><div class="card"><h2>Weka Matokeo</h2><form id="resultForm" class="form"><select id="rMatch" required><option value="">Chagua mechi</option></select><input id="rHome" type="number" min="0" value="0" required><input id="rAway" type="number" min="0" value="0" required><input id="rHP" type="number" min="0" placeholder="Home penalties (optional)"><input id="rAP" type="number" min="0" placeholder="Away penalties (optional)"><button class="btn">Maliza Mechi</button><div id="resultMsg"></div></form></div></div><section class="card" id="matchList"><h2>Mechi</h2><div class="list"></div></section>');
 const loadSeasons=async()=>{mSeason.innerHTML='<option value="">Msimu</option>';mStage.innerHTML='<option value="">Stage (optional)</option>';mHome.innerHTML='<option value="">Home</option>';mAway.innerHTML='<option value="">Away</option>';if(!mLeague.value)return;const r=await db.from("seasons").select("id,name,status").eq("league_id",mLeague.value).order("start_date",{ascending:false});mSeason.innerHTML='<option value="">Msimu</option>'+(r.data||[]).map(x=>'<option value="'+x.id+'">'+esc(x.name)+' · '+esc(x.status)+'</option>').join("")};
 const loadStageTeams=async()=>{mStage.innerHTML='<option value="">Stage (optional)</option>';mHome.innerHTML='<option value="">Home</option>';mAway.innerHTML='<option value="">Away</option>';if(!mSeason.value)return;const [st,tr]=await Promise.all([db.from("competition_stages").select("id,name,stage_type").eq("league_id",mLeague.value).eq("season_id",mSeason.value).order("stage_order"),db.from("teams").select("id,name").eq("league_id",mLeague.value).eq("season_id",mSeason.value).order("name")]);mStage.innerHTML='<option value="">Stage (optional)</option>'+(st.data||[]).map(x=>'<option value="'+x.id+'">'+esc(x.name)+' · '+esc(x.stage_type)+'</option>').join("");const opts=(tr.data||[]).map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join("");mHome.innerHTML='<option value="">Home</option>'+opts;mAway.innerHTML='<option value="">Away</option>'+opts};
 mLeague.onchange=loadSeasons;mSeason.onchange=loadStageTeams;
 const load=async()=>{const x=await db.from("matches").select("id,scheduled_at,home_score,away_score,status,round_name,home_team:teams!matches_home_team_id_fkey(name),away_team:teams!matches_away_team_id_fkey(name),leagues(name),seasons(name)").neq("status","finished").order("scheduled_at");rMatch.innerHTML='<option value="">Chagua mechi</option>'+(x.data||[]).map(m=>'<option value="'+m.id+'">'+esc(m.home_team?.name)+' vs '+esc(m.away_team?.name)+' · '+fmt(m.scheduled_at)+'</option>').join("");document.querySelector("#matchList .list").innerHTML=(x.data||[]).map(m=>'<div class="row"><span><b>'+esc(m.home_team?.name)+' vs '+esc(m.away_team?.name)+'</b><small>'+esc(m.leagues?.name||"")+' · '+esc(m.seasons?.name||"")+' · '+fmt(m.scheduled_at)+' · '+esc(m.status)+'</small></span><span><a class="btn" href="#/admin/matches/live/'+m.id+'">Live</a> <a class="btn" href="#/admin/matches/lineup/'+m.id+'">Lineup</a></span></div>').join("")||'<div class="empty">Hakuna mechi bado.</div>'};await load();
 matchForm.onsubmit=async e=>{e.preventDefault();matchMsg.textContent="Inahifadhi...";if(mHome.value===mAway.value)return matchMsg.textContent="Home na Away lazima zitofautiane.";const [home,away]=await Promise.all([db.from("teams").select("league_id,season_id").eq("id",mHome.value).single(),db.from("teams").select("league_id,season_id").eq("id",mAway.value).single()]);if(home.error||away.error||home.data.league_id!==mLeague.value||away.data.league_id!==mLeague.value||home.data.season_id!==mSeason.value||away.data.season_id!==mSeason.value){matchMsg.textContent="Timu zote lazima ziwe za ligi na msimu huo.";return}const x=await db.from("matches").insert({league_id:mLeague.value,season_id:mSeason.value,stage_id:mStage.value||null,home_team_id:mHome.value,away_team_id:mAway.value,scheduled_at:new Date(mDate.value).toISOString(),venue:mVenue.value.trim()||null,round_name:mRound.value.trim()||null,leg_number:Number(mLeg.value)||1,status:"scheduled",home_score:0,away_score:0}).select("id").single();matchMsg.textContent=x.error?x.error.message:"Fixture imehifadhiwa.";if(!x.error){e.target.reset();await loadStageTeams();load()}};
 resultForm.onsubmit=async e=>{e.preventDefault();const x=await db.rpc("record_match_result",{p_match_id:rMatch.value,p_home_score:Number(rHome.value),p_away_score:Number(rAway.value),p_home_penalties:rHP.value===""?null:Number(rHP.value),p_away_penalties:rAP.value===""?null:Number(rAP.value)});resultMsg.textContent=x.error?x.error.message:"Matokeo yamehifadhiwa na standings/progression zimesasishwa.";if(!x.error){await load();rHome.value=0;rAway.value=0}};
}
